#!/usr/bin/env python3
from __future__ import annotations
import argparse,base64,datetime as dt,importlib.util,os,py_compile,shutil,subprocess,sys
from pathlib import Path

VERSION='0.6.0'
MODIFIED_B64={'backend/app/api/v1/endpoints/sampling_geometry_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_labs/sampling_geometry/program.py': {'old': '', 'new': ''}, 'backend/app/services/vision_labs/sampling_geometry/program_runtime.py': {'old': '', 'new': ''}, 'backend/app/services/vision_labs/sampling_geometry/session.py': {'old': '', 'new': ''}, 'backend/app/services/vision_labs/service/runtime.py': {'old': '', 'new': ''}, 'backend/tests/vision_labs/sampling_geometry/test_sampling_program_v0500.py': {'old': '', 'new': ''}, 'frontend/src/Pages/SamplingGeometryLabPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/samplingGeometryApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/VisionLabs/SamplingProgram/SamplingOutputShapeDesigner.tsx': {'old': '', 'new': ''}, 'frontend/src/components/VisionLabs/SamplingProgram/SamplingStructurePanel.tsx': {'old': '', 'new': ''}, 'frontend/src/components/VisionLabs/SamplingProgram/types.ts': {'old': '', 'new': ''}, 'frontend/src/components/VisionLabs/SamplingProgram/useSamplingProgramController.ts': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64={'backend/tests/vision_labs/sampling_geometry/test_sampling_program_v0600.py': '', 'frontend/docs/llm_context/updates/v0600_sampling_output_formulation.md': ''}
MODIFIED={k:{'old':base64.b64decode(v['old']).decode('utf-8'),'new':base64.b64decode(v['new']).decode('utf-8')} for k,v in MODIFIED_B64.items()}
CREATED={k:base64.b64decode(v).decode('utf-8') for k,v in CREATED_B64.items()}

def resolve_roots(frontend_arg=None,backend_arg=None):
    cwd=Path.cwd().resolve();fes=[];bes=[]
    if frontend_arg:fes.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:bes.append(Path(backend_arg).expanduser().resolve())
    fes += [cwd,cwd/'LambdaVisionSuper',cwd.parent/'LambdaVisionSuper']
    bes += [cwd,cwd/'LambdaVisionSuperBackEnd',cwd.parent/'LambdaVisionSuperBackEnd']
    fe=next((p for p in fes if (p/'src/App.tsx').exists() and (p/'src/Pages/SamplingGeometryLabPage.tsx').exists()),None)
    be=next((p for p in bes if (p/'app/main.py').exists() and (p/'app/services/vision_labs/sampling_geometry').exists()),None)
    if fe is None: raise RuntimeError('Cannot locate LambdaVisionSuper frontend; use --frontend PATH')
    if be is None: raise RuntimeError('Cannot locate LambdaVisionSuperBackEnd; use --backend PATH')
    return fe,be

def path_for(fe,be,v):
    if v.startswith('frontend/'): return fe/v[len('frontend/'):]
    if v.startswith('backend/'): return be/v[len('backend/'):]
    raise ValueError(v)

def state_modified(path,old,new):
    if not path.exists():return 'MISSING'
    cur=path.read_text(encoding='utf-8')
    if cur==new:return 'OK'
    if cur==old:return 'UPDATE'
    return 'CONFLICT'

def state_created(path,desired):
    if not path.exists():return 'CREATE'
    return 'OK' if path.read_text(encoding='utf-8')==desired else 'CONFLICT'

def scan(fe,be):
    print('='*100);print('SAMPLING LAB V0.6.0 — OUTPUT FORMULATION WORKSPACE');print('='*100)
    print('Frontend :',fe);print('Backend  :',be);print();conflicts=0
    for v,p in MODIFIED.items():
        st=state_modified(path_for(fe,be,v),p['old'],p['new']);print(f'  [{st:10}] {v}');conflicts += st in {'CONFLICT','MISSING'}
    for v,d in CREATED.items():
        st=state_created(path_for(fe,be,v),d);print(f'  [{st:10}] {v}');conflicts += st=='CONFLICT'
    print();print('v0.6 contract:')
    print('  Sampling image -> semantic Data Blocks -> cached Formulation')
    print('  Final Sampling outputs: Vector [N] or 2-D Matrix [R x C] only')
    print('  Formulate button reshapes cached blocks without re-running image sampling')
    print('  Local Vector: patch-major or feature-major')
    print('  Local Matrix: patches x features OR features x patches')
    print('  Tensor depth/channel stacking is deferred to Representation LAB')
    print('  sampling_program_v1 services remain runnable; editor migrates editable v1 snapshots to v2')
    print('  LLM context generator + v0.6 architecture handoff note included')
    if conflicts:print(f'\n[WARN] {conflicts} conflict/base issue(s); apply will stop safely.')
    return 0

def preflight(fe,be):
    errors=[]
    for v,p in MODIFIED.items():
        st=state_modified(path_for(fe,be,v),p['old'],p['new'])
        if st not in {'UPDATE','OK'}:errors.append(f'{v}: {st}')
    for v,d in CREATED.items():
        st=state_created(path_for(fe,be,v),d)
        if st not in {'CREATE','OK'}:errors.append(f'{v}: {st}')
    app=(fe/'src/App.tsx').read_text(encoding='utf-8');api=(be/'app/api/v1/api.py').read_text(encoding='utf-8')
    if '/labs/sampling-geometry' not in app:errors.append('frontend/src/App.tsx: Sampling LAB route missing')
    if 'sampling_geometry_api' not in api:errors.append('backend/app/api/v1/api.py: Sampling API router missing')
    if errors:raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(errors))

def backup(fe,be,paths):
    stamp=dt.datetime.now().strftime('%Y%m%d_%H%M%S');root=fe/'.lambda_updater_backups'/f'sampling_lab_v0600_{stamp}';root.mkdir(parents=True,exist_ok=True)
    for p in paths:
        if not p.exists():continue
        try:rel=p.relative_to(fe);dst=root/'frontend'/rel
        except ValueError:rel=p.relative_to(be);dst=root/'backend'/rel
        dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dst)
    return root

def regenerate_context(fe,be):
    g=fe/'tools/generate_llm_context_map.py'
    if not g.exists():print('[SKIP] context generator missing');return
    cmd=[sys.executable,str(g),'--frontend',str(fe),'--backend',str(be)]
    if '--output-dir' in g.read_text(encoding='utf-8'):cmd += ['--output-dir',str(fe/'docs/llm_context')]
    p=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
    if p.returncode:raise RuntimeError('Context regeneration failed:\n'+(p.stdout+'\n'+p.stderr).strip())
    if p.stdout.strip():print(p.stdout.strip())

def apply(fe,be):
    preflight(fe,be);targets=[path_for(fe,be,v) for v in list(MODIFIED)+list(CREATED)];root=backup(fe,be,targets)
    for v,p in MODIFIED.items():
        path=path_for(fe,be,v)
        if path.read_text(encoding='utf-8')!=p['new']:path.write_text(p['new'],encoding='utf-8');print('[WRITE]',v)
    for v,d in CREATED.items():
        path=path_for(fe,be,v);path.parent.mkdir(parents=True,exist_ok=True)
        if not path.exists() or path.read_text(encoding='utf-8')!=d:path.write_text(d,encoding='utf-8');print('[WRITE]',v)
    print('[INFO] Regenerating LLM context docs...');regenerate_context(fe,be);print('[OK] Backup:',root);print('Run verify next.');return 0

def py_syntax(be):
    bad=[];count=0
    for v in list(MODIFIED)+list(CREATED):
        if v.startswith('backend/') and v.endswith('.py'):
            count+=1
            try:py_compile.compile(str(path_for(Path('/unused'),be,v)),doraise=True)
            except Exception as e:bad.append(f'{v}: {e}')
    return count,bad

def ts_transpile(fe):
    files=[path_for(fe,Path('/unused'),v) for v in list(MODIFIED)+list(CREATED) if v.startswith('frontend/') and v.endswith(('.ts','.tsx'))]
    code=r'''const fs=require("fs"),ts=require("typescript");let bad=false;for(const f of process.argv.slice(1)){const s=fs.readFileSync(f,"utf8");const r=ts.transpileModule(s,{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}});const es=(r.diagnostics||[]).filter(d=>d.category===ts.DiagnosticCategory.Error);if(es.length){bad=true;console.error("TS_ERROR",f);for(const e of es)console.error(ts.flattenDiagnosticMessageText(e.messageText,"\\n"));}}process.exit(bad?1:0);'''
    env=dict(os.environ);nr=subprocess.run(['npm','root','-g'],text=True,capture_output=True)
    if nr.returncode==0 and nr.stdout.strip():env['NODE_PATH']=nr.stdout.strip()+(os.pathsep+env['NODE_PATH'] if env.get('NODE_PATH') else '')
    return subprocess.run(['node','-e',code,*map(str,files)],cwd=str(fe),env=env,text=True,capture_output=True)

def backend_smoke(be):
    code=r'''
import numpy as np
from app.services.vision_labs.image.types import ImageFrame,ColorSpace
from app.services.vision_labs.sampling_geometry.program import SamplingProgramDefinition,LegacySamplingProgramDefinition,sampling_program_sample_signature
from app.services.vision_labs.sampling_geometry.program_runtime import SamplingProgramRuntime
from app.services.vision_labs.sampling_geometry.session import SamplingGeometrySession
img=np.zeros((80,120,3),np.uint8);img[...,0]=np.tile(np.arange(120,dtype=np.uint8),(80,1));img[...,1]=100;frame=ImageFrame(img,ColorSpace.BGR)
def p(layout='matrix',axis='patch_rows',order='patch_major'):
 return SamplingProgramDefinition(**{'global_domain':{'methods':[{'id':'hist','kind':'histogram','channels':['gray'],'measures':['histogram'],'histogram_bins':8}]},'local_domain':{'grid':{'rows':2,'cols':3},'methods':[{'id':'stats','kind':'statistics','channels':['gray','r'],'measures':['mean','std']},{'id':'cross','kind':'cross','channels':['gray'],'measures':['profile'],'sample_count':6,'parameters':{'length_ratio':.8}}]},'output_shape':{'local_layout':layout,'local_matrix_axis':axis,'local_vector_order':order}})
program=p();rt=SamplingProgramRuntime(program);sample=rt.sample(frame);matrix=rt.formulate(sample,program.output_shape);vector=rt.formulate(sample,p('vector',order='feature_major').output_shape);columns=rt.formulate(sample,p('matrix','patch_columns').output_shape)
assert len(matrix.local_data.shape)==2 and matrix.local_data.shape[0]==6
assert len(vector.local_data.shape)==1 and vector.local_data.shape[0]==np.asarray(matrix.local_data.values).size
assert columns.local_data.shape==matrix.local_data.shape[::-1]
assert 'feature_depth' not in matrix.local_data.metadata
assert sampling_program_sample_signature(program)==sampling_program_sample_signature(p('vector',order='feature_major'))
s=SamplingGeometrySession();sig=sampling_program_sample_signature(program);s.set_program_sample(sample,sig);assert s.get_program_sample(sig) is sample
legacy=LegacySamplingProgramDefinition(**{'local_domain':{'grid':{'rows':2,'cols':3},'methods':[{'id':'stats','kind':'statistics','channels':['gray'],'measures':['mean']}]},'output_shape':{'local_layout':'spatial_tensor','local_order':'patch_major'}});legacy_run=SamplingProgramRuntime(legacy).run(frame);assert len(legacy_run.local_data.shape)==3
print('SAMPLING_V0600_SMOKE_OK',matrix.local_data.shape,vector.local_data.shape,columns.local_data.shape,legacy_run.local_data.shape)
'''
    return subprocess.run([sys.executable,'-c',code],cwd=str(be),text=True,capture_output=True)

def verify(fe,be,skip_build=False):
    print('='*100);print('VERIFY SAMPLING LAB V0.6.0');print('='*100);fail=0
    page=(fe/'src/Pages/SamplingGeometryLabPage.tsx').read_text(encoding='utf-8');designer=(fe/'src/components/VisionLabs/SamplingProgram/SamplingOutputShapeDesigner.tsx').read_text(encoding='utf-8');controller=(fe/'src/components/VisionLabs/SamplingProgram/useSamplingProgramController.ts').read_text(encoding='utf-8');types=(fe/'src/components/VisionLabs/SamplingProgram/types.ts').read_text(encoding='utf-8');program=(be/'app/services/vision_labs/sampling_geometry/program.py').read_text(encoding='utf-8');runtime=(be/'app/services/vision_labs/sampling_geometry/program_runtime.py').read_text(encoding='utf-8');session=(be/'app/services/vision_labs/sampling_geometry/session.py').read_text(encoding='utf-8');api=(be/'app/api/v1/endpoints/sampling_geometry_api.py').read_text(encoding='utf-8');service=(be/'app/services/vision_labs/service/runtime.py').read_text(encoding='utf-8');gen=(fe/'tools/generate_llm_context_map.py').read_text(encoding='utf-8')
    checks=[
      ('Sampling Program v2 model','sampling_program_v2' in program and 'version: int = 6' in program),
      ('New Sampling output scope is Vector / Matrix only','Literal["vector", "matrix"]' in program and "'spatial_tensor'" not in types),
      ('Sample -> Formulate runtime split','def sample(self, frame' in runtime and 'def formulate(self, sample' in runtime),
      ('Session caches sampled Data Blocks','program_sample_signature' in session and 'get_program_sample' in session),
      ('Formulate REST endpoint','/program/formulate' in api and 'formulation_only=True' in api),
      ('Frontend calls cached Formulate endpoint','formulateProgram' in (fe/'src/api/samplingGeometryApi.ts').read_text(encoding='utf-8') and 'formulateNow' in controller),
      ('Output Formulation Workspace has Formulate button','OUTPUT FORMULATION WORKSPACE' in designer and 'Formulate</button>' in designer),
      ('Vector shape visual is segmented and indexed','SegmentedVector' in designer and 'index 0' in designer),
      ('2-D matrix shape visual has semantic axes','Final 2-D plane' in designer and 'rows = patches' in designer and 'columns = patches' in designer),
      ('Sampling page removes tensor/depth ownership','Vector / 2-D Matrix formulation' in page and 'Features / patch' in page),
      ('Representation LAB boundary documented','Representation LAB' in designer and 'Representation LAB' in gen),
      ('Legacy Sampling Program v1 service compatibility','LegacySamplingProgramDefinition' in program and 'sampling_program_v1' in service),
      ('v0.6 MD handoff note',(fe/'docs/llm_context/updates/v0600_sampling_output_formulation.md').exists()),
      ('Context generator knows cached formulation','cached Data Blocks' in gen and 'Output Formulation Workspace' in gen),
    ]
    for label,ok in checks:print(f'[{"OK" if ok else "FAIL"}] {label}');fail += 0 if ok else 1
    count,bad=py_syntax(be)
    if bad:print('[FAIL] Python syntax');[print('  -',x) for x in bad];fail+=len(bad)
    else:print(f'[OK] Python syntax ({count} changed/new backend files)')
    smoke=backend_smoke(be)
    if smoke.returncode==0:print('[OK] Sampling v0.6 backend smoke');print(smoke.stdout.strip())
    else:print('[FAIL] backend smoke');print((smoke.stdout+'\n'+smoke.stderr).strip());fail+=1
    tests=[p for p in ['tests/vision_labs/sampling_geometry/test_sampling_program_v0600.py','tests/vision_labs/sampling_geometry/test_sampling_program_v0500.py','tests/vision_labs/sampling_geometry/test_sampling_lab_v0400.py','tests/vision_labs/sampling_geometry/test_sampling_geometry_lab_v0200.py'] if (be/p).exists()]
    if importlib.util.find_spec('pytest') is None:print('[SKIP] pytest unavailable')
    elif tests:
        pr=subprocess.run([sys.executable,'-m','pytest','-q',*tests],cwd=str(be),text=True,capture_output=True)
        if pr.returncode==0:print('[OK] Sampling regression tests');print(pr.stdout.strip())
        else:print('[FAIL] Sampling regression tests');print((pr.stdout+'\n'+pr.stderr).strip());fail+=1
    ts=ts_transpile(fe);txt=(ts.stdout+'\n'+ts.stderr).strip()
    if ts.returncode==0:print('[OK] TypeScript syntax/transpile')
    elif 'Cannot find module' in txt or 'MODULE_NOT_FOUND' in txt:print('[SKIP] TypeScript module unavailable')
    else:print('[FAIL] TypeScript syntax/transpile');print(txt);fail+=1
    if not skip_build and (fe/'package.json').exists() and (fe/'node_modules').exists():
        pr=subprocess.run(['npm','run','build'],cwd=str(fe))
        if pr.returncode==0:print('[OK] Frontend npm build')
        else:print('[FAIL] Frontend npm build');fail+=1
    else:print('[SKIP] Frontend npm build')
    try:
        regenerate_context(fe,be);arch=fe/'docs/llm_context/SYSTEM_ARCHITECTURE.md';bundles=fe/'docs/llm_context/SYSTEM_CONTEXT_BUNDLES.md';ok=arch.exists() and bundles.exists() and 'Output Formulation Workspace' in arch.read_text(encoding='utf-8') and 'Sampling LAB' in bundles.read_text(encoding='utf-8');print(f'[{"OK" if ok else "FAIL"}] Regenerated LLM context docs');fail += 0 if ok else 1
    except Exception as e:print('[FAIL] Context regeneration:',e);fail+=1
    if fail:print(f'[FAIL] v0.6.0 verification finished with {fail} issue(s).');return 1
    print('[OK] Sampling LAB v0.6.0 Output Formulation Workspace verified.');return 0

def main():
    ap=argparse.ArgumentParser();ap.add_argument('command',choices=['scan','apply','verify']);ap.add_argument('--frontend');ap.add_argument('--backend');ap.add_argument('--skip-build',action='store_true');a=ap.parse_args()
    try:
        fe,be=resolve_roots(a.frontend,a.backend)
        if a.command=='scan':return scan(fe,be)
        if a.command=='apply':return apply(fe,be)
        return verify(fe,be,a.skip_build)
    except Exception as e:print('[ERROR]',e);return 2
if __name__=='__main__':raise SystemExit(main())
